const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define northeastern Pacific Ocean region
  const nePacific = ee.Geometry.Polygon([
    [[-180, 30], [-120, 30], [-120, 60], [-180, 60], [-180, 30]]
  ]);

  // 2. Load SST data for August 2019
  const sst2019 = ee.ImageCollection('NOAA/CDR/OISST/V2_1')
    .filterDate('2019-08-01', '2019-09-01')
    .filterBounds(nePacific)
    .select('sst');

  const count2019 = sst2019.size().getInfo();
  console.log(`August 2019 images: ${count2019}`);

  if (count2019 === 0) {
    console.log('No data for August 2019.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Load SST data for August 1985-2012
  const sstHistorical = ee.ImageCollection('NOAA/CDR/OISST/V2_1')
    .filter(ee.Filter.calendarRange(8, 8, 'month'))
    .filter(ee.Filter.calendarRange(1985, 2012, 'year'))
    .filterBounds(nePacific)
    .select('sst');

  const countHistorical = sstHistorical.size().getInfo();
  console.log(`August 1985-2012 images: ${countHistorical}`);

  if (countHistorical === 0) {
    console.log('No historical data for August 1985-2012.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Calculate mean SST for both periods
  const mean2019 = sst2019.mean();
  const meanHistorical = sstHistorical.mean();

  // 5. Get regional statistics
  const stats2019 = mean2019.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: nePacific,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const statsHistorical = meanHistorical.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: nePacific,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const sst2019Mean = stats2019.sst_mean;
  const sst2019Count = stats2019.sst_count;
  const sstHistMean = statsHistorical.sst_mean;
  const sstHistCount = statsHistorical.sst_count;

  console.log(`2019 Mean SST: ${sst2019Mean ? sst2019Mean.toFixed(2) : 'null'}°C, Pixels: ${sst2019Count || 0}`);
  console.log(`1985-2012 Mean SST: ${sstHistMean ? sstHistMean.toFixed(2) : 'null'}°C, Pixels: ${sstHistCount || 0}`);

  // 6. Validation and answer
  if (!sst2019Count || sst2019Count === 0 || !sstHistCount || sstHistCount === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (sst2019Mean === null || sst2019Mean === undefined || 
      sstHistMean === null || sstHistMean === undefined ||
      isNaN(sst2019Mean) || isNaN(sstHistMean)) {
    console.log('Calculation failed - invalid results.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Check for reasonable SST range (-2°C to 35°C)
  if (sst2019Mean < -2 || sst2019Mean > 35 || sstHistMean < -2 || sstHistMean > 35) {
    console.log('SST values out of reasonable range.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Difference (2019 - Historical): ${(sst2019Mean - sstHistMean).toFixed(2)}°C`);

  if (sst2019Mean < sstHistMean) {
    console.log('August 2019 was cooler than 1985-2012 average.');
    console.log('<answer>A</answer>');
  } else {
    console.log('August 2019 was not cooler than 1985-2012 average.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
